package main

import "fmt"

// increment takes a pointer to an int and mutates the caller's value.
func increment(n *int) {
	*n++ // dereference n, then increment the int it points to
}

// swap exchanges the two ints the pointers refer to.
func swap(a, b *int) {
	*a, *b = *b, *a
}

func main() {
	x := 5
	p := &x // p is of type *int, holding the address of x

	fmt.Println("x =", x)        // 5
	fmt.Println("p points to", *p) // 5 (dereference)

	*p = 42 // write through the pointer; x changes too
	fmt.Println("x after *p=42 ->", x) // 42

	increment(&x)                       // pass x's address
	fmt.Println("x after increment ->", x) // 43

	a, b := 1, 2
	swap(&a, &b)
	fmt.Printf("a=%d b=%d\n", a, b) // a=2 b=1
}

package main

import "fmt"

type Counter struct {
	n int
}

// Value receiver: operates on a COPY, so changes do not persist.
func (c Counter) IncByValue() {
	c.n++ // mutates the copy only
}

// Pointer receiver: operates on the original, so changes persist.
func (c *Counter) IncByPointer() {
	c.n++ // c is *Counter; c.n is shorthand for (*c).n
}

func (c Counter) String() string {
	return fmt.Sprintf("Counter(%d)", c.n)
}

func main() {
	c := Counter{}

	c.IncByValue()
	fmt.Println("after IncByValue:", c) // Counter(0) - unchanged

	c.IncByPointer() // Go auto-takes &c because c is addressable
	c.IncByPointer()
	fmt.Println("after IncByPointer x2:", c) // Counter(2)

	p := &Counter{n: 10}
	p.IncByPointer()
	fmt.Println("via pointer var:", *p) // Counter(11)
}

package main

import "fmt"

type Config struct {
	Name    string
	Retries int
}

// newConfig returns a pointer to a heap-allocated Config.
// Because the address escapes (it is returned), escape analysis
// allocates it on the heap. Verify with: go build -gcflags=-m
func newConfig(name string) *Config {
	c := Config{Name: name, Retries: 3} // c escapes to heap
	return &c
}

// describe is defensive: it tolerates a nil pointer.
func describe(c *Config) string {
	if c == nil {
		return "<no config>"
	}
	return fmt.Sprintf("%s (retries=%d)", c.Name, c.Retries)
}

func main() {
	// Two equivalent allocation idioms:
	a := new(Config)        // *Config pointing at zeroed Config
	b := &Config{}          // same: zeroed Config, address taken
	c := &Config{Name: "x"} // composite literal with fields set

	fmt.Println(a.Retries, b.Retries, c.Name) // 0 0 x

	cfg := newConfig("prod")
	fmt.Println(describe(cfg)) // prod (retries=3)

	var nilCfg *Config // zero value is nil
	fmt.Println(describe(nilCfg)) // <no config> (no panic)

	// Uncommenting the next line panics:
	// runtime error: invalid memory address or nil pointer dereference
	// fmt.Println(nilCfg.Name)
}
